page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state shown = 0
  ref box
  ref t0
  ref started

  fn tick(now) {
    let p = Math.min((now - t0) / 2000, 1)
    shown = Math.round(12000 * (1 - Math.pow(1 - p, 3)))
    if p < 1 {
      requestAnimationFrame(tick)
    }
  }

  fn run() {
    if started { return }
    started = true
    if matchMedia("(prefers-reduced-motion: reduce)").matches {
      shown = 12000
      return
    }
    t0 = performance.now()
    requestAnimationFrame(tick)
  }

  mount {
    let io = new IntersectionObserver(es => es[0].isIntersecting && run(), { threshold: 0.4 })
    io.observe(box)
    cleanup { io.disconnect() }
  }

  style {
    .hero {
      background: linear-gradient(120deg, #6366f1, #06b6d4, #a855f7, #ec4899, #6366f1);
      background-size: 300% 300%;
      animation: drift 18s ease-in-out infinite;
      color: #fff;
      min-height: 70vh;
      border-radius: 0 0 24px 24px;
    }
    @keyframes drift {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    @media (prefers-reduced-motion: reduce) {
      .hero { animation: none; }
    }
    .hero-sub { opacity: 0.9; max-width: 480px; text-align: center; }
    .stat { font-size: 4rem; font-weight: 800; }
  }

  column gap=12 {
    column class="hero" align=center justify=center gap=4 pad=8 {
      title "Nimbus" tag=h1 large animate=rise
      text "La forma más ligera de llevar tus ideas a la nube." class="hero-sub" large animate=fade delay=200
      button "Empezar" primary hover=grow animate=pop delay=400 -> navigate("/signup")
    }

    grid cols=1 md:cols=3 gap=4 pad=6 {
      card pad=6 gap=2 reveal hover=lift {
        title "Rápido" tag=h3
        text "Carga en milisegundos, siempre."
      }
      card pad=6 gap=2 reveal hover=lift {
        title "Simple" tag=h3
        text "Sin configuraciones complicadas."
      }
      card pad=6 gap=2 reveal hover=lift {
        title "Abierto" tag=h3
        text "Código abierto y hecho con la comunidad."
      }
    }

    column ref=box align=center gap=1 pad=8 {
      text `${shown.toLocaleString("es-AR")}+` class="stat"
      text "usuarios" muted
    }
  }
}

