  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    let observer: IntersectionObserver | null = null;
    try {
      observer = new IntersectionObserver(
        (entries) => {
          if (entries.some((e) => e.isIntersecting)) {
            setInView(true);
            observer?.disconnect();
          }
        },
        { threshold }
      );
      observer.observe(el);
    } catch {
      setInView(true);
    }
    return () => observer?.disconnect();
  }, [threshold]);

  return { ref, inView };
}

interface CardProps {
  title: string;
  text: string;
  index: number;
  reduced: boolean;
}

