      setValue(Math.round(eased * target));
      if (progress >= 1) clearInterval(id);
    }, 32);
    return () => clearInterval(id);
  }, [inView, reduced, target]);

  return (
    <div ref={ref} className="text-center">
      <div className="text-6xl font-extrabold tabular-nums text-slate-900 sm:text-7xl">
        {formatNumber(value)}+
      </div>
      <p className="mt-2 text-lg text-slate-600">usuarios</p>
