function Counter({ target, reduced }: { target: number; reduced: boolean }) {
  const { ref, inView } = useInView<HTMLDivElement>(0.4);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    const duration = 1500;
    const startTime = Date.now();
    const id = setInterval(() => {
      const progress = Math.min((Date.now() - startTime) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(progress >= 1 ? target : Math.round(eased * target));
      if (progress >= 1) clearInterval(id);
    }, 30);
    // Garantiza el valor final aunque los intervalos se throttleen.
    const done = setTimeout(() => {
      clearInterval(id);
      setValue(target);
    }, duration + 50);
    return () => {
      clearInterval(id);
      clearTimeout(done);
    };
  }, [inView, reduced, target]);

  return (
    <div ref={ref} className="text-center">
      <div className="text-6xl font-extrabold tabular-nums text-slate-900 sm:text-7xl">
