    }
    return () => anim?.cancel();
  }, [reduced]);

  return (
    <div
      ref={ref}
      aria-hidden="true"
      style={{ backgroundSize: "300% 300%" }}
      className="absolute inset-0 bg-gradient-to-br from-indigo-500 via-sky-400 to-fuchsia-500"
