interface CounterProps {
  target: number;
  duration: number;
}

export default function Counter(props: CounterProps) {
  let el!: HTMLDivElement;
  const [value, setValue] = createSignal(0);
  let raf = 0;
  let timer: number | undefined;
  let started = false;

  const format = (n: number) =>
    new Intl.NumberFormat("es-AR").format(Math.round(n));

  const start = () => {
    if (started) return;
    started = true;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setValue(props.target);
      return;
    }

    const t0 = performance.now();
    const tick = (now: number) => {
      const p = Math.min((now - t0) / props.duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      setValue(props.target * eased);
      if (p < 1) raf = requestAnimationFrame(tick);
      else setValue(props.target);
    };
    raf = requestAnimationFrame(tick);

    // Garantiza el valor final aunque rAF se pause o se throttlee
    timer = window.setTimeout(() => {
      cancelAnimationFrame(raf);
      setValue(props.target);
    }, props.duration + 50);
  };

  onMount(() => {
    if (!("IntersectionObserver" in window)) {
      start();
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          start();
          io.disconnect();
        }
      },
      { threshold: 0.5 }
    );
    io.observe(el);
    onCleanup(() => io.disconnect());
  });

  onCleanup(() => {
    cancelAnimationFrame(raf);
    if (timer !== undefined) clearTimeout(timer);
  });

  return (
    <div
      ref={el}
      class="text-6xl md:text-8xl font-extrabold tabular-nums bg-gradient-to-r from-sky-400 to-fuchsia-500 bg-clip-text text-transparent"
      aria-label={`${format(props.target)}+`}
    >
      {format(value())}+
    </div>
  );
}

