  reduced: boolean;
}

export default function Counter(props: CounterProps) {
  let el!: HTMLDivElement;
  const [value, setValue] = createSignal(0);
  let raf = 0;
  let started = false;

  const format = (n: number) =>
    new Intl.NumberFormat("es-AR").format(Math.round(n));

  const prefersReduced = () =>
    props.reduced ||
    (typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches);

  const start = () => {
    if (started) return;
    started = true;
    if (prefersReduced()) {
      setValue(props.target);
      return;
    }
    const t0 = performance.now();
    const tick = (now: number) => {
      const p = Math.min((now - t0) / props.duration, 1);
      if (p >= 1) {
        setValue(props.target);
        return;
      }
      const eased = 1 - Math.pow(1 - p, 3);
      setValue(props.target * eased);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  };

  onMount(() => {
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          start();
          io.disconnect();
        }
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    onCleanup(() => {
      io.disconnect();
      cancelAnimationFrame(raf);
    });
  });

  return (
    <div
      ref={el}
      class="bg-gradient-to-r from-sky-400 to-fuchsia-400 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-8xl"
    >
      {format(value())}+
    </div>
  );
}
